//! The solver catalog: every model family, selectable type and keyword urbanMicroclimateFoam
//! reads, for OpenFOAM-8 and OpenFOAM-12.
//!
//! The data (`catalog/generated.rs`) is produced from the `solver/` submodule by
//! `cargo xtask catalog`, and CI checks it still matches the pinned solver. Nothing here is
//! typed by hand, so the GUI can't offer a type the solver doesn't have.

use umcf_core::OfVersion;

// Generated by `cargo xtask catalog`, which also checks it byte for byte: rustfmt stays out.
#[rustfmt::skip]
mod generated;

#[derive(Debug)]
pub struct Catalog {
    /// The `solver/` commit the catalog was generated from (the OpenFOAM-12 port).
    pub solver_commit: &'static str,
    /// The commit of the `of-org_v8.0` tag.
    pub v8_commit: &'static str,
    pub families: &'static [Family],
    pub types: &'static [SolverType],
    pub app_keywords: &'static [AppKeywords],
    /// Files the solver and its models read when they start.
    pub fields: &'static [FieldRead],
    /// The classes the solver constructs (`<class>::New`) for each kind of region.
    pub builds: &'static [RegionBuild],
}

/// Where a field is read from.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum FieldInstance {
    /// The time the run starts from.
    StartTime,
    /// `0`, whatever time the run starts from.
    Zero,
    /// `constant/<region>`.
    Constant,
    /// The mesh's directory or elsewhere: files the radiation utilities write.
    Other,
}

/// Who reads a field.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum FieldOwner {
    /// The solver, for every region of a kind (`fluid`, `solid`, `vegetation`).
    Region(&'static str),
    /// A family's base class, whichever type is selected.
    Family(&'static str),
    /// One selectable type.
    Type { family: &'static str, name: &'static str },
    /// A utility or library file.
    Other(&'static str),
}

/// A file read through an `IOobject` with `MUST_READ` (`required`) or `READ_IF_PRESENT`.
#[derive(Debug)]
pub struct FieldRead {
    pub name: &'static str,
    pub owner: FieldOwner,
    pub instance: FieldInstance,
    pub required: bool,
    pub file: &'static str,
    pub versions: &'static [OfVersion],
}

/// A class the solver constructs for every region of a kind (`vegetationModel` for `fluid`).
#[derive(Debug)]
pub struct RegionBuild {
    pub region: &'static str,
    pub class: &'static str,
    pub versions: &'static [OfVersion],
}

/// A base class with run-time selection: building materials, vegetation, grass, solar load, …
#[derive(Debug)]
pub struct Family {
    pub base: &'static str,
    /// The keyword whose value picks the type (`grassModel simpleGrass;`).
    pub selector: Option<&'static str>,
    /// The dictionary the selector is read from (`grassProperties`), when the family reads one.
    pub dict_file: Option<&'static str>,
    pub source: &'static str,
    pub versions: &'static [OfVersion],
    /// Keywords the base class reads for every type of the family.
    pub keywords: &'static [Keyword],
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum TypeKind {
    Model,
    ScalarBoundaryCondition,
    VectorBoundaryCondition,
    RasModel,
}

/// A type a case can select, by the name it is written with (`HamstadBrick`,
/// `compressible::CFDHAMsolidTemperatureCoupledMixed`).
#[derive(Debug)]
pub struct SolverType {
    pub name: &'static str,
    /// The C++ class.
    pub class: &'static str,
    /// The family's base class, or `fvPatchScalarField` / `fvPatchVectorField` / `RASModel`.
    pub family: &'static str,
    pub kind: TypeKind,
    pub source: &'static str,
    pub versions: &'static [OfVersion],
    pub keywords: &'static [Keyword],
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Access {
    /// `lookup("key")`: the case must have it.
    Required,
    /// `lookupOrDefault("key", default)`: the default as written in the source.
    Default(&'static str),
    /// `found("key")` / `readIfPresent("key", …)`.
    Optional,
    /// `subDict("key")`.
    SubDict,
}

#[derive(Debug)]
pub struct Keyword {
    pub name: &'static str,
    pub access: Access,
    /// What the key is looked up in, as written in the source (`dict`, `coeffs_`).
    pub receiver: &'static str,
    pub versions: &'static [OfVersion],
}

/// Keywords the solver, its utilities or its libraries read outside the model classes.
#[derive(Debug)]
pub struct AppKeywords {
    /// `urbanMicroclimateFoam`, a utility (`solarRayTracingGen`), or `lib/<library>`.
    pub app: &'static str,
    pub file: &'static str,
    pub keywords: &'static [Keyword],
}

/// The catalog of the pinned solver.
pub fn catalog() -> &'static Catalog {
    &generated::CATALOG
}

impl Catalog {
    pub fn family(&self, base: &str) -> Option<&'static Family> {
        self.families.iter().find(|f| f.base == base)
    }

    /// Types of a family (or of `fvPatchScalarField`, …), every version.
    pub fn types_of(&self, family: &str) -> impl Iterator<Item = &'static SolverType> + use<'_> {
        let types: &'static [SolverType] = self.types;
        let family = family.to_string();
        types.iter().filter(move |t| t.family == family)
    }

    pub fn find(&self, family: &str, name: &str) -> Option<&'static SolverType> {
        self.types.iter().find(|t| t.family == family && t.name == name)
    }

    /// The names a case for `version` may select in a family, sorted.
    pub fn choices(&self, family: &str, version: OfVersion) -> Vec<&'static str> {
        let mut out: Vec<&'static str> =
            self.types_of(family).filter(|t| t.versions.contains(&version)).map(|t| t.name).collect();
        out.sort_unstable();
        out
    }

    /// Boundary conditions the solver adds, for `version`.
    pub fn boundary_conditions(&self, version: OfVersion) -> impl Iterator<Item = &'static SolverType> {
        let types: &'static [SolverType] = self.types;
        types.iter().filter(move |t| {
            matches!(t.kind, TypeKind::ScalarBoundaryCondition | TypeKind::VectorBoundaryCondition)
                && t.versions.contains(&version)
        })
    }
}

impl SolverType {
    pub fn in_version(&self, v: OfVersion) -> bool {
        self.versions.contains(&v)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn families_have_selectors_and_types() {
        let c = catalog();
        assert_eq!(c.solver_commit.len(), 40);
        for base in ["buildingMaterialModel", "grassModel", "solarLoadModel", "vegetationModel"] {
            let f = c.family(base).unwrap_or_else(|| panic!("no family {base}"));
            assert_eq!(f.selector, Some(base), "{base}");
            assert!(c.types_of(base).count() >= 2, "{base}");
        }
        assert_eq!(c.family("grassModel").and_then(|f| f.dict_file), Some("grassProperties"));
        assert_eq!(c.family("vegetationModel").and_then(|f| f.dict_file), Some("vegetationProperties"));
    }

    #[test]
    fn versions_differ_where_the_solver_does() {
        let c = catalog();
        let osb = c.find("buildingMaterialModel", "OSB").unwrap();
        assert!(osb.in_version(OfVersion::V12) && !osb.in_version(OfVersion::V8));
        let brick = c.find("buildingMaterialModel", "HamstadBrick").unwrap();
        assert!(brick.in_version(OfVersion::V8) && brick.in_version(OfVersion::V12));
        assert!(c.choices("buildingMaterialModel", OfVersion::V12).contains(&"OSB"));
        assert!(!c.choices("buildingMaterialModel", OfVersion::V8).contains(&"OSB"));
    }

    #[test]
    fn boundary_conditions_and_keywords() {
        let c = catalog();
        let bc = c.find("fvPatchScalarField", "compressible::CFDHAMsolidTemperatureCoupledMixed").unwrap();
        assert_eq!(bc.kind, TypeKind::ScalarBoundaryCondition);
        assert!(bc.keywords.iter().any(|k| k.name == "qrNbr" && k.access == Access::Default("\"none\"")));
        assert!(c.boundary_conditions(OfVersion::V12).count() >= 10);
        assert_eq!(c.find("RASModel", "porousrealizableKE").map(|t| t.kind), Some(TypeKind::RasModel));
        // The solver reads its regions from controlDict in the OpenFOAM-12 port only.
        let regions = c
            .app_keywords
            .iter()
            .filter(|a| a.app == "urbanMicroclimateFoam")
            .flat_map(|a| a.keywords)
            .find(|k| k.name == "regions" && k.access == Access::SubDict)
            .unwrap();
        assert_eq!(regions.versions, [OfVersion::V12]);
    }

    #[test]
    fn names_are_unique_per_family() {
        let c = catalog();
        let mut seen = std::collections::BTreeSet::new();
        for t in c.types {
            assert!(seen.insert((t.family, t.name)), "{} {}", t.family, t.name);
            assert!(!t.versions.is_empty());
        }
    }
}
